// Reads OpenTelemetry spans (the OTLP JSON shape) into Orlune spans. The point: you can feed a trace you already
// collect to TraceExplorer and RunInspector without mapping it by hand, and nothing is invented on the way. A span
// with no cost attribute has no cost, and a status OpenTelemetry does not have is never filled in.
import type { Span, SpanKind, SpanStatus } from '../components/trace'

type AnyValue = { stringValue?: string; intValue?: string | number; doubleValue?: number; boolValue?: boolean }
type KeyValue = { key: string; value?: AnyValue }
export type OtlpSpan = {
  traceId?: string
  spanId: string
  parentSpanId?: string
  name: string
  startTimeUnixNano: string | number
  endTimeUnixNano: string | number
  attributes?: KeyValue[]
  /** 0 unset, 1 ok, 2 error. */
  status?: { code?: number | string; message?: string }
}
export type OtlpExport = { resourceSpans?: { scopeSpans?: { spans?: OtlpSpan[] }[] }[] }

export type FromOtlpOptions = {
  /** Only this trace. Without it, every trace in the export is returned and ids are made unique per trace. */
  traceId?: string
  /** Where a cost is kept, if you record one. OpenTelemetry has no standard attribute for it. */
  costAttribute?: string
  /** Decide the kind yourself. Return undefined to use the built-in reading. */
  kindOf?: (span: OtlpSpan, attrs: Record<string, string | number | boolean>) => SpanKind | undefined
}

function scalar(v?: AnyValue): string | number | boolean | undefined {
  if (!v) return undefined
  if (v.stringValue !== undefined) return v.stringValue
  if (v.intValue !== undefined) return Number(v.intValue)
  if (v.doubleValue !== undefined) return v.doubleValue
  if (v.boolValue !== undefined) return v.boolValue
  return undefined
}

function attrsOf(list?: KeyValue[]): Record<string, string | number | boolean> {
  const out: Record<string, string | number | boolean> = {}
  for (const kv of list ?? []) {
    const v = scalar(kv.value)
    if (v !== undefined) out[kv.key] = v
  }
  return out
}

const OPENINFERENCE: Record<string, SpanKind> = { LLM: 'llm', TOOL: 'tool', RETRIEVER: 'retrieval', RERANKER: 'retrieval', EMBEDDING: 'retrieval', AGENT: 'agent', CHAIN: 'agent' }
const GENAI_OPERATION: Record<string, SpanKind> = {
  chat: 'llm', text_completion: 'llm', generate_content: 'llm', execute_tool: 'tool', invoke_agent: 'agent', create_agent: 'agent', embeddings: 'retrieval', retrieval: 'retrieval',
}

/** From the OpenInference span kind, then the GenAI operation name, then the span name. Anything else is "agent". */
export function kindFromAttributes(name: string, attrs: Record<string, string | number | boolean>): SpanKind {
  const oi = attrs['openinference.span.kind']
  if (typeof oi === 'string' && OPENINFERENCE[oi.toUpperCase()]) return OPENINFERENCE[oi.toUpperCase()]!
  const op = attrs['gen_ai.operation.name']
  if (typeof op === 'string' && GENAI_OPERATION[op]) return GENAI_OPERATION[op]!
  if (attrs['gen_ai.tool.name'] !== undefined) return 'tool'
  if (/retriev|vector|embed/i.test(name)) return 'retrieval'
  return 'agent'
}

const nano = (v: string | number) => {
  try { return BigInt(typeof v === 'number' ? Math.round(v) : v) } catch { return 0n }
}

/** One Orlune span per OTLP span. Times are milliseconds from the earliest start, so they are exact to the microsecond. */
export function spansFromOtlp(data: OtlpExport, options: FromOtlpOptions = {}): Span[] {
  const raw: OtlpSpan[] = []
  for (const rs of data.resourceSpans ?? []) for (const ss of rs.scopeSpans ?? []) for (const s of ss.spans ?? []) raw.push(s)
  const picked = options.traceId ? raw.filter((s) => s.traceId === options.traceId) : raw
  if (picked.length === 0) return []
  const traces = new Set(picked.map((s) => s.traceId ?? ''))
  const key = (s: OtlpSpan, id: string) => (traces.size > 1 ? `${s.traceId ?? ''}:${id}` : id)
  const t0 = picked.reduce((m, s) => { const t = nano(s.startTimeUnixNano); return t < m ? t : m }, nano(picked[0]!.startTimeUnixNano))
  return picked.map((s): Span => {
    const attrs = attrsOf(s.attributes)
    const start = nano(s.startTimeUnixNano)
    const end = nano(s.endTimeUnixNano)
    const code = Number(s.status?.code ?? 0)
    const status: SpanStatus = code === 2 || String(s.status?.code).toUpperCase() === 'STATUS_CODE_ERROR' ? 'error' : 'ok'
    const tin = attrs['gen_ai.usage.input_tokens']
    const tout = attrs['gen_ai.usage.output_tokens']
    const cost = options.costAttribute ? attrs[options.costAttribute] : undefined
    const input = attrs['gen_ai.tool.call.arguments'] ?? attrs['input.value'] ?? attrs['gen_ai.input.messages']
    const output = attrs['gen_ai.tool.call.result'] ?? attrs['output.value'] ?? attrs['gen_ai.output.messages']
    return {
      id: key(s, s.spanId),
      parentId: s.parentSpanId ? key(s, s.parentSpanId) : undefined,
      name: s.name,
      kind: options.kindOf?.(s, attrs) ?? kindFromAttributes(s.name, attrs),
      startMs: Number(start - t0) / 1e6,
      durationMs: Math.max(0, Number(end - start) / 1e6),
      status,
      attrs,
      ...(input !== undefined ? { input } : {}),
      ...(output !== undefined ? { output } : s.status?.message ? { output: s.status.message } : {}),
      ...(typeof tin === 'number' || typeof tout === 'number' ? { tokens: { in: typeof tin === 'number' ? tin : 0, out: typeof tout === 'number' ? tout : 0 } } : {}),
      ...(typeof cost === 'number' ? { costUsd: cost } : {}),
    }
  })
}

// Reads AI SDK message parts into the steps PlanVsActual compares. The point: a tool call is "ok" only when the
// message says it produced an output, and a call still waiting or never answered is not counted as having run.
import type { ActualStep } from '../components/planactual'

/** The parts of an AI SDK UI message that matter here. Other parts (text, reasoning, files) are ignored. */
export type AiSdkPart = {
  type: string
  toolCallId?: string
  toolName?: string
  state?: string
  input?: unknown
  output?: unknown
  errorText?: string
  approval?: { approved?: boolean }
}
export type AiSdkMessage = { id?: string; role?: string; parts?: AiSdkPart[] }

export type FromAiSdkOptions = {
  /** Turn a tool name into the words shown on the page. Defaults to the name with dashes and underscores as spaces. */
  label?: (toolName: string) => string
  /** Tool name to the plan step it was meant to carry out. */
  planIds?: Record<string, string>
}

const PREFIX = 'tool-'
const words = (n: string) => n.replace(/[-_]+/g, ' ').replace(/([a-z])([A-Z])/g, '$1 $2').trim().toLowerCase()

/** The tool name of a part, or undefined when the part is not a tool call. */
export function toolNameOf(p: AiSdkPart): string | undefined {
  if (p.type === 'dynamic-tool') return p.toolName
  return p.type.startsWith(PREFIX) ? p.type.slice(PREFIX.length) : undefined
}

/**
 * One step per tool call, in message order. `output-available` is ok, `output-error` is error and a call the person
 * denied is blocked. A call still streaming or waiting for an approval or an output is left out, because it has not
 * run yet and counting it would hide a step that never happened.
 */
export function stepsFromAiSdk(messages: AiSdkMessage[], options: FromAiSdkOptions = {}): ActualStep[] {
  const steps: ActualStep[] = []
  messages.forEach((m, mi) => {
    ;(m.parts ?? []).forEach((p, pi) => {
      const name = toolNameOf(p)
      if (!name) return
      let status: ActualStep['status'] | undefined
      if (p.state === 'output-available') status = 'ok'
      else if (p.state === 'output-error') status = 'error'
      else if (p.state === 'output-denied' || p.approval?.approved === false) status = 'blocked'
      if (!status) return
      steps.push({
        id: p.toolCallId ?? `${m.id ?? mi}:${pi}`,
        action: options.label ? options.label(name) : words(name),
        status,
        ...(options.planIds?.[name] ? { planId: options.planIds[name] } : {}),
      })
    })
  })
  return steps
}

// Maps a LangGraph / LangChain human-in-the-loop interrupt to approval queue items and back. The point: the reviewer
// sees the exact tool call the agent paused on, and what goes back is only what the reviewer decided. Nothing is
// invented on the way in: no evidence is made up, and an action not known to be undoable is shown as not undoable.
import type { Decision, DecisionKind, QueueItem } from '../components/approval'

/** What `stream.interrupt.value` holds for the built-in human-in-the-loop middleware. */
export type HitlRequest = {
  actionRequests: { name: string; args: Record<string, unknown>; description?: string }[]
  reviewConfigs: { allowedDecisions: ('approve' | 'reject' | 'edit' | 'respond')[] }[]
}
export type HitlDecision =
  | { type: 'approve' }
  | { type: 'reject'; message?: string }
  | { type: 'edit'; editedAction: { name: string; args: Record<string, unknown> } }
  | { type: 'respond'; message: string }
export type HitlResponse = { decisions: HitlDecision[] }

export type FromInterruptOptions = {
  /** An id for this interrupt. Items are named `<id>:0`, `<id>:1` and so on. */
  id: string
  /** Who the reviewer sees as having asked. Defaults to "agent". */
  requester?: string
  /** LangChain does not say how risky a call is. Defaults to "medium". */
  risk?: (name: string) => QueueItem['risk']
  /** LangChain does not say whether a call can be undone. Anything you do not say is shown as not undoable. */
  reversible?: (name: string) => QueueItem['reversible']
  expiresAt?: string
}

const words = (n: string) => n.replace(/[-_]+/g, ' ').replace(/([a-z])([A-Z])/g, '$1 $2').trim().toLowerCase()
const same = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b)

/** The plan an item carries for one action request. It is what gets hashed, so an edit to it is a new plan. */
export type CallPlan = { tool: string; args: Record<string, unknown> }

export function itemsFromInterrupt(req: HitlRequest, o: FromInterruptOptions): QueueItem[] {
  return req.actionRequests.map((a, i) => {
    const allowedDecisions = req.reviewConfigs[i]?.allowedDecisions ?? ['approve', 'reject']
    const allowed: DecisionKind[] = []
    if (allowedDecisions.includes('approve') || allowedDecisions.includes('edit')) allowed.push('approve')
    if (allowedDecisions.includes('reject')) allowed.push('reject')
    if (allowedDecisions.includes('respond')) allowed.push('respond')
    const plan: CallPlan = { tool: a.name, args: a.args }
    return {
      id: `${o.id}:${i}`,
      action: words(a.name),
      summary: a.description ?? `The agent paused before running ${words(a.name)}.`,
      requester: o.requester ?? 'agent',
      risk: o.risk?.(a.name) ?? 'medium',
      plan,
      expiresAt: o.expiresAt,
      evidence: [],
      reversible: o.reversible?.(a.name) ?? false,
      needs: 1,
      decisions: [],
      allowed,
      editable: allowedDecisions.includes('edit'),
    }
  })
}

export type ReviewerDecision = { kind: DecisionKind; message?: string }
export type ToResponseResult = { ok: true; response: HitlResponse } | { ok: false; problem: string }

/**
 * Builds the value to resume the graph with, from what the reviewer decided on each item. It refuses to answer for a
 * reviewer: an item with no decision, or a decision the interrupt did not allow, is a problem, not a guess. An approval
 * of a plan whose arguments were edited becomes an `edit`. Escalating has no LangChain equivalent, so it is sent as a
 * rejection that says so.
 */
export function responseFromDecisions(req: HitlRequest, id: string, items: QueueItem[], decisions: Record<string, ReviewerDecision | Decision | undefined>): ToResponseResult {
  const out: HitlDecision[] = []
  for (let i = 0; i < req.actionRequests.length; i++) {
    const action = req.actionRequests[i]!
    const key = `${id}:${i}`
    const d = decisions[key]
    const kind = d ? ('kind' in d ? d.kind : d.decision) : undefined
    const message = d?.message
    if (!kind) return { ok: false, problem: `No decision yet for ${words(action.name)}.` }
    const allowed = req.reviewConfigs[i]?.allowedDecisions ?? ['approve', 'reject']
    if (kind === 'approve') {
      const plan = items.find((x) => x.id === key)?.plan as CallPlan | undefined
      if (plan && !same(plan.args, action.args)) {
        if (!allowed.includes('edit')) return { ok: false, problem: `Editing ${words(action.name)} is not allowed here.` }
        out.push({ type: 'edit', editedAction: { name: action.name, args: plan.args } })
      } else if (allowed.includes('approve')) out.push({ type: 'approve' })
      else return { ok: false, problem: `Approving ${words(action.name)} is not allowed here.` }
    } else if (kind === 'reject') {
      if (!allowed.includes('reject')) return { ok: false, problem: `Rejecting ${words(action.name)} is not allowed here.` }
      out.push({ type: 'reject', ...(message ? { message } : {}) })
    } else if (kind === 'respond') {
      if (!allowed.includes('respond')) return { ok: false, problem: `Replying to ${words(action.name)} is not allowed here.` }
      if (!message) return { ok: false, problem: `Write the reply for ${words(action.name)}.` }
      out.push({ type: 'respond', message })
    } else {
      if (!allowed.includes('reject')) return { ok: false, problem: `Escalating ${words(action.name)} needs a rejection, which is not allowed here.` }
      out.push({ type: 'reject', message: message ?? 'Escalated to someone with more authority. Do not run this.' })
    }
  }
  return { ok: true, response: { decisions: out } }
}
